import io
import json
import pandas as pd


def read_sales(text):
    if not text or not text.strip():
        return []
    try:
        df = pd.read_csv(
            io.StringIO(text),
            dtype={'product': str, 'quantity': int, 'price': str},
        )
    except pd.errors.EmptyDataError:
        return []

    sales = []
    for row in df.to_dict('records'):
        sales.append({
            'product': str(row['product']),
            'quantity': int(row['quantity']),
            'price': float(str(row['price']).replace(',', '')),
        })
    return sales


def totals(sales):
    by_product = {}
    for row in sales:
        product = str(row['product'])
        amount = int(row['quantity']) * float(row['price'])
        by_product[product] = by_product.get(product, 0.0) + amount
    return {product: float(amount) for product, amount in by_product.items()}


def save_report(path, sales):
    by_product = totals(sales)
    total = sum(by_product.values())
    best = max(by_product, key=by_product.get) if by_product else None
    report = {
        'total': 0 if not by_product else float(total),
        'by_product': {str(product): float(amount) for product, amount in by_product.items()},
        'best': best,
    }
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(report, f)


def load_report(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

