        return float(value.replace(",", ""))
    return float(value)


def read_sales(text):
    if text.strip() == "":
        return []
    df = pd.read_csv(io.StringIO(text))
    sales = []
    for row in df.to_dict("records"):
        sales.append({
            "product": row["product"],
            "quantity": int(row["quantity"]),
            "price": _price_number(row["price"]),
        })
    return sales


def totals(sales):
    by_product = {}
